prompt:
The library function `ledger::transfer` only promises that balances stay within the cap. Give it a postcondition that states what it does: if it returns true, account i lost x and account j gained x; if it returns false, accounts i and j are unchanged; every other account is unchanged either way. Keep its parameters, precondition and behaviour. Change other definitions if the proof needs it; the whole workspace must still verify.

Required signature (in unit `ledger`):
fn transfer(a: &mut [i64], i: usize, j: usize, x: i64) -> (r: bool)

reference.code:
spec fn dep_cond(b: &[i64], i: usize, x: i64, r: bool) -> bool { r == (b[i] <= 1000000000 - x) }

spec fn wd_cond(b: &[i64], i: usize, x: i64, r: bool) -> bool { r == (b[i] >= x) }

spec fn transferred(a: &[i64], b: &[i64], i: usize, j: usize, x: i64, r: bool) -> bool {
    a.len() == b.len() && (r ==> a[i] == b[i] - x && a[j] == b[j] + x) && (!r ==> a[i] == b[i] && a[j] == b[j]) && (forall|k: usize| k < a.len() && k != i && k != j ==> #[trigger] a[k] == b[k])
}

#[effects(pure)]
#[uses(cap_ok, acct, amount_ok, moved, credited, dep_cond)]
fn deposit(a: &mut [i64], i: usize, x: i64) -> (r: bool)
    requires cap_ok(a), acct(a, i), amount_ok(x),
    ensures cap_ok(a), credited(a, old(a), i, x, r), dep_cond(old(a), i, x, r),
{
    if a[i] <= 1000000000 - x {
        a[i] = a[i] + x;
        true
    } else {
        false
    }
}

#[effects(pure)]
#[uses(cap_ok, acct, amount_ok, moved, debited, wd_cond)]
fn withdraw(a: &mut [i64], i: usize, x: i64) -> (r: bool)
    requires cap_ok(a), acct(a, i), amount_ok(x),
    ensures cap_ok(a), debited(a, old(a), i, x, r), wd_cond(old(a), i, x, r),
{
    if a[i] >= x {
        a[i] = a[i] - x;
        true
    } else {
        false
    }
}

#[effects(pure)]
#[uses(cap_ok, acct, amount_ok, moved, credited, debited, dep_cond, wd_cond, transferred)]
fn transfer(a: &mut [i64], i: usize, j: usize, x: i64) -> (r: bool)
    requires cap_ok(a), acct(a, i), acct(a, j), amount_ok(x),
    ensures cap_ok(a), transferred(a, old(a), i, j, x, r),
{
    let mut ok: bool = false;
    if i != j && a[i] >= x && a[j] <= 1000000000 - x {
        let w: bool = withdraw(a, i, x);
        let d: bool = deposit(a, j, x);
        ok = w && d;
    }
    ok
}

